require_once __DIR__.'/app/lib/Security.php';Security::start();$u=Security::requireRole(['reviewer','admin','super_admin']);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relationship Claims | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f8fafc;color:#1e293b}.wrap{max-width:1180px;margin:28px auto;padding:0 20px}.toolbar,.card{background:#fff;border:1px solid #dce6ed;border-radius:14px;padding:16px;margin-bottom:14px}.toolbar{display:flex;gap:10px;flex-wrap:wrap}.toolbar input,.toolbar select{padding:10px;border:1px solid #cfd8e3;border-radius:8px}.grid{display:grid;grid-template-columns:380px 1fr;gap:14px}.item{padding:12px;border-bottom:1px solid #eef2f7;cursor:pointer}.item:hover{background:#f8fbfd}.pill{font-size:12px;background:#eef4f8;padding:4px 7px;border-radius:999px}.meta{font-size:12px;color:#64748b}.detail a{word-break:break-all}.actions button{margin:6px 6px 0 0;padding:9px 11px;border:0;border-radius:8px;background:#123b67;color:#fff;font-weight:700}.actions .danger{background:#991b1b}.actions .muted{background:#475569}textarea{width:100%;min-height:80px;box-sizing:border-box;margin-top:10px;padding:10px;border:1px solid #cfd8e3;border-radius:8px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Vendor relationship claims</h1><p>Review reseller, distributor, implementation, referral and local-agent claims before they become verified public relationships.</p><div class="toolbar"><select id="status"><option value="">All statuses</option><option>pending</option><option>under_review</option><option>needs_information</option><option>verified</option><option>rejected</option><option>revoked</option></select><input id="q" placeholder="Search company, software or submitter"><button id="load">Filter</button></div><div class="grid"><div class="card" id="list"></div><div class="card detail" id="detail">Select a claim.</div></div></main><script>const csrf=<?php echo json_encode($csrf)?>;let current=null;async function load(){const p=new URLSearchParams();if(status.value)p.set('status',status.value);if(q.value)p.set('q',q.value);const r=await fetch('/api/vendor-relationship-claims-admin?'+p);const j=await r.json();list.innerHTML=(j.items||[]).map(x=>`<div class="item" data-id="${x.id}"><strong>${x.vendor_name}</strong> → ${x.product_name}<br><span class="pill">${x.relationship_type}</span> <span class="pill">${x.status}</span><div class="meta">${x.submitter_email} · ${x.created_at}</div></div>`).join('')||'No claims';document.querySelectorAll('.item').forEach(el=>el.onclick=()=>show(el.dataset.id))}async function show(id){const r=await fetch('/api/vendor-relationship-claims-admin/'+id);const x=await r.json();current=x;let t=[];try{t=JSON.parse(x.territories_json||'[]')}catch(e){}detail.innerHTML=`<h2>${x.vendor_name} → ${x.product_name}</h2><p><span class="pill">${x.relationship_type}</span> <span class="pill">${x.status}</span></p><p><strong>Territories:</strong> ${t.map(v=>v.name+' ('+v.code+')').join(', ')}</p><p><strong>Evidence:</strong> ${x.evidence_type}</p>${x.evidence_url?`<p><a href="${x.evidence_url}" target="_blank" rel="noopener">${x.evidence_url}</a></p>`:''}<p>${x.evidence_reference||''}</p><p>${x.evidence_note||''}</p><p class="meta">Submitter: ${x.submitter_email}${x.valid_until?' · Valid until '+x.valid_until:''}</p><textarea id="note" placeholder="Reviewer note / reason"></textarea><div class="actions"><button onclick="act('start_review')">Start review</button><button class="muted" onclick="act('request_information')">Request information</button><button onclick="act('approve')">Verify relationship</button><button class="danger" onclick="act('reject')">Reject</button>${x.relationship_id?'<button class="danger" onclick="act(\'revoke\')">Revoke verified relationship</button>':''}</div><h3>History</h3>${(x.history||[]).map(h=>`<div class="meta">${h.created_at} · ${h.action} · ${h.from_status||'-'} → ${h.to_status}${h.note?' · '+h.note:''}</div>`).join('')||'<div class="meta">No review history yet.</div>'}`;}async function act(action){if(!current)return;const note=document.getElementById('note').value;const r=await fetch('/api/vendor-relationship-claims-admin/'+current.id+'/action',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action,note})});const j=await r.json();if(!r.ok){alert(j.error||'Failed');return}await load();await show(current.id)}document.getElementById('load').onclick=load;load();</script></body></html>